\section*{{\cjkfont 繁\hspace{0pt}體\hspace{0pt}中\hspace{0pt}文\hspace{0pt}摘\hspace{0pt}要\hspace{0pt}}}
{\cjkfont\raggedright
本\hspace{0pt}研\hspace{0pt}究\hspace{0pt}探\hspace{0pt}討\hspace{0pt}：在\hspace{0pt}兩\hspace{0pt}個\hspace{0pt}來\hspace{0pt}源\hspace{0pt}鎖\hspace{0pt}定\hspace{0pt}的\hspace{0pt}緊\hspace{0pt}緻\hspace{0pt}虧\hspace{0pt}格\hspace{0pt}二\hspace{0pt}雙\hspace{0pt}曲\hspace{0pt}曲\hspace{0pt}面\hspace{0pt}上\hspace{0pt}，何\hspace{0pt}種\hspace{0pt}精\hspace{0pt}確\hspace{0pt}憑\hspace{0pt}證\hspace{0pt}架\hspace{0pt}構\hspace{0pt}可\hspace{0pt}支\hspace{0pt}援\hspace{0pt}原\hspace{0pt}始\hspace{0pt}閉\hspace{0pt}測\hspace{0pt}地\hspace{0pt}線\hspace{0pt}的\hspace{0pt}所\hspace{0pt}有\hspace{0pt}權\hspace{0pt}判\hspace{0pt}定\hspace{0pt}。研\hspace{0pt}究\hspace{0pt}對\hspace{0pt}象\hspace{0pt}固\hspace{0pt}定\hspace{0pt}為\hspace{0pt} Bolza 目\hspace{0pt}標\hspace{0pt}曲\hspace{0pt}面\hspace{0pt}與\hspace{0pt}一\hspace{0pt}個\hspace{0pt}非\hspace{0pt}算\hspace{0pt}術\hspace{0pt}控\hspace{0pt}制\hspace{0pt}曲\hspace{0pt}面\hspace{0pt}，動\hspace{0pt}力\hspace{0pt}學\hspace{0pt}子\hspace{0pt}型\hspace{0pt}固\hspace{0pt}定\hspace{0pt}為\hspace{0pt}單\hspace{0pt}位\hspace{0pt}速\hspace{0pt}率\hspace{0pt}的\hspace{0pt}物\hspace{0pt}理\hspace{0pt}基\hspace{0pt}底\hspace{0pt}測\hspace{0pt}地\hspace{0pt}時\hspace{0pt}間\hspace{0pt}、磁\hspace{0pt}場\hspace{0pt}參\hspace{0pt}數\hspace{0pt} $b=1/2$ 及\hspace{0pt}有\hspace{0pt}號\hspace{0pt}磁\hspace{0pt}場\hspace{0pt}的\hspace{0pt}偶\hspace{0pt}數\hspace{0pt}子\hspace{0pt}序\hspace{0pt}列\hspace{0pt}；共\hspace{0pt}同\hspace{0pt}截\hspace{0pt}斷\hspace{0pt}值\hspace{0pt}維\hspace{0pt}持\hspace{0pt}為\hspace{0pt} $\Lambda=21/10$，且\hspace{0pt}不\hspace{0pt}得\hspace{0pt}依\hspace{0pt}已\hspace{0pt}知\hspace{0pt}方\hspace{0pt}向\hspace{0pt}重\hspace{0pt}新\hspace{0pt}調\hspace{0pt}整\hspace{0pt}。本\hspace{0pt}研\hspace{0pt}究\hspace{0pt}實\hspace{0pt}際\hspace{0pt}執\hspace{0pt}行\hspace{0pt}的\hspace{0pt}是\hspace{0pt}封\hspace{0pt}閉\hspace{0pt}語\hspace{0pt}料\hspace{0pt}的\hspace{0pt}文\hspace{0pt}獻\hspace{0pt}查\hspace{0pt}核\hspace{0pt}、證\hspace{0pt}據\hspace{0pt}整\hspace{0pt}合\hspace{0pt}及\hspace{0pt}方\hspace{0pt}法\hspace{0pt}設\hspace{0pt}計\hspace{0pt}，並\hspace{0pt}未\hspace{0pt}執\hspace{0pt}行\hspace{0pt}測\hspace{0pt}地\hspace{0pt}線\hspace{0pt}普\hspace{0pt}查\hspace{0pt}、共\hspace{0pt}軛\hspace{0pt}判\hspace{0pt}定\hspace{0pt}、原\hspace{0pt}始\hspace{0pt}根\hspace{0pt}判\hspace{0pt}定\hspace{0pt}、數\hspace{0pt}值\hspace{0pt}實\hspace{0pt}驗\hspace{0pt}或\hspace{0pt}路\hspace{0pt}線\hspace{0pt}圖\hspace{0pt}評\hspace{0pt}分\hspace{0pt}。綜\hspace{0pt}合\hspace{0pt}結\hspace{0pt}果\hspace{0pt}支\hspace{0pt}持\hspace{0pt}一\hspace{0pt}項\hspace{0pt}受\hspace{0pt}限\hspace{0pt}架\hspace{0pt}構\hspace{0pt}：兩\hspace{0pt}個\hspace{0pt}曲\hspace{0pt}面\hspace{0pt}可\hspace{0pt}採\hspace{0pt}用\hspace{0pt}各\hspace{0pt}自\hspace{0pt}專\hspace{0pt}屬\hspace{0pt}的\hspace{0pt}精\hspace{0pt}確\hspace{0pt}證\hspace{0pt}明\hspace{0pt}產\hspace{0pt}生\hspace{0pt}器\hspace{0pt}，但\hspace{0pt}輸\hspace{0pt}出\hspace{0pt}必\hspace{0pt}須\hspace{0pt}進\hspace{0pt}入\hspace{0pt}共\hspace{0pt}同\hspace{0pt}的\hspace{0pt}語\hspace{0pt}義\hspace{0pt}憑\hspace{0pt}證\hspace{0pt}綱\hspace{0pt}要\hspace{0pt}，再\hspace{0pt}由\hspace{0pt}獨\hspace{0pt}立\hspace{0pt}驗\hspace{0pt}證\hspace{0pt}器\hspace{0pt}檢\hspace{0pt}查\hspace{0pt}。綱\hspace{0pt}要\hspace{0pt}須\hspace{0pt}分\hspace{0pt}離\hspace{0pt}完\hspace{0pt}整\hspace{0pt}群\hspace{0pt}共\hspace{0pt}軛\hspace{0pt}、最\hspace{0pt}大\hspace{0pt}根\hspace{0pt}與\hspace{0pt}原\hspace{0pt}始\hspace{0pt}性\hspace{0pt}、外\hspace{0pt}部\hspace{0pt}反\hspace{0pt}元\hspace{0pt}素\hspace{0pt}配\hspace{0pt}對\hspace{0pt}、自\hspace{0pt}互\hspace{0pt}反\hspace{0pt}性\hspace{0pt}、重\hspace{0pt}複\hspace{0pt}軌\hspace{0pt}道\hspace{0pt}、終\hspace{0pt}止\hspace{0pt}性\hspace{0pt}、完\hspace{0pt}備\hspace{0pt}性\hspace{0pt}，以\hspace{0pt}及\hspace{0pt}正\hspace{0pt}面\hspace{0pt}或\hspace{0pt}負\hspace{0pt}面\hspace{0pt}的\hspace{0pt}重\hspace{0pt}播\hspace{0pt}證\hspace{0pt}據\hspace{0pt}。共\hspace{0pt}同\hspace{0pt}語\hspace{0pt}義\hspace{0pt}不\hspace{0pt}要\hspace{0pt}求\hspace{0pt}共\hspace{0pt}同\hspace{0pt}的\hspace{0pt}內\hspace{0pt}部\hspace{0pt}演\hspace{0pt}算\hspace{0pt}法\hspace{0pt}或\hspace{0pt}數\hspace{0pt}值\hspace{0pt}表\hspace{0pt}示\hspace{0pt}。目\hspace{0pt}標\hspace{0pt}端\hspace{0pt}空\hspace{0pt}集\hspace{0pt}合\hspace{0pt}與\hspace{0pt}控\hspace{0pt}制\hspace{0pt}端\hspace{0pt}非\hspace{0pt}空\hspace{0pt}集\hspace{0pt}合\hspace{0pt}的\hspace{0pt}方\hspace{0pt}向\hspace{0pt}，均\hspace{0pt}僅\hspace{0pt}是\hspace{0pt}未\hspace{0pt}驗\hspace{0pt}證\hspace{0pt}的\hspace{0pt}繼\hspace{0pt}承\hspace{0pt}架\hspace{0pt}構\hspace{0pt}假\hspace{0pt}設\hspace{0pt}。若\hspace{0pt}日\hspace{0pt}後\hspace{0pt}分\hspace{0pt}別\hspace{0pt}以\hspace{0pt}來\hspace{0pt}源\hspace{0pt}與\hspace{0pt}假\hspace{0pt}設\hspace{0pt}充\hspace{0pt}分\hspace{0pt}的\hspace{0pt}證\hspace{0pt}明\hspace{0pt}記\hspace{0pt}錄\hspace{0pt}成\hspace{0pt}功\hspace{0pt}重\hspace{0pt}播\hspace{0pt}，才\hspace{0pt}可\hspace{0pt}把\hspace{0pt}相\hspace{0pt}應\hspace{0pt}方\hspace{0pt}向\hspace{0pt}作\hspace{0pt}為\hspace{0pt}條\hspace{0pt}件\hspace{0pt}式\hspace{0pt}的\hspace{0pt}產\hspace{0pt}生\hspace{0pt}器\hspace{0pt}輸\hspace{0pt}入\hspace{0pt}；在\hspace{0pt}此\hspace{0pt}之\hspace{0pt}前\hspace{0pt}，兩\hspace{0pt}端\hspace{0pt}差\hspace{0pt}異\hspace{0pt}不\hspace{0pt}得\hspace{0pt}支\hspace{0pt}持\hspace{0pt}空\hspace{0pt}與\hspace{0pt}非\hspace{0pt}空\hspace{0pt}比\hspace{0pt}較\hspace{0pt}、算\hspace{0pt}術\hspace{0pt}性\hspace{0pt}推\hspace{0pt}論\hspace{0pt}、A0/A1/A2 關\hspace{0pt}閉\hspace{0pt}、Route A 計\hspace{0pt}分\hspace{0pt}或\hspace{0pt} Route B 進\hspace{0pt}展\hspace{0pt}。P33-RC-1 的\hspace{0pt}七\hspace{0pt}項\hspace{0pt}義\hspace{0pt}務\hspace{0pt}仍\hspace{0pt}為\hspace{0pt}零\hspace{0pt}項\hspace{0pt}完\hspace{0pt}成\hspace{0pt}；產\hspace{0pt}生\hspace{0pt}器\hspace{0pt}、綱\hspace{0pt}要\hspace{0pt}、驗\hspace{0pt}證\hspace{0pt}器\hspace{0pt}與\hspace{0pt}普\hspace{0pt}查\hspace{0pt}均\hspace{0pt}未\hspace{0pt}實\hspace{0pt}作\hspace{0pt}。本\hspace{0pt}文\hspace{0pt}的\hspace{0pt}落\hspace{0pt}地\hspace{0pt}成\hspace{0pt}果\hspace{0pt}是\hspace{0pt}可\hspace{0pt}稽\hspace{0pt}核\hspace{0pt}的\hspace{0pt}憑\hspace{0pt}證\hspace{0pt}方\hspace{0pt}法\hspace{0pt}設\hspace{0pt}計\hspace{0pt}，而\hspace{0pt}不\hspace{0pt}是\hspace{0pt}已\hspace{0pt}完\hspace{0pt}成\h